import { CallToAction, ExistingThemes } from "@/core/types";
import { SpokenText } from "@/core/components/primitives/spoken-text/spoken-text";
import {
  GhostButton,
  SecondaryButtonLink,
  buttonUrlFromCallToAction,
} from "@/core/components/primitives/parks-button/parks-button";
import styles from "./hero-block.module.less";
import { multipleClassNames } from "@/core/helpers/string-helper";
import { RichTextType } from "@/core/components/primitives/rich-text/rich-text";
import { Options, documentToReactComponents } from "@contentful/rich-text-react-renderer";
import { BLOCKS, MARKS } from "@contentful/rich-text-types";
import { GatsbyImage, IGatsbyImageData } from "gatsby-plugin-image";
import { RefObject, useEffect, useRef, useState } from "react";
import { useCurrentContentPageSlugsContext } from "@/core/contexts/current-content-page-context";
import { useTranslation } from "react-i18next";
import { breakpoints } from "@/core/constants/breakpoints";

const MAX_TILT_DEGREES = 20;
const MIN_TILT_DEGREES = -20;

export const T_SHIRT_SIZES = ["xxs", "xs", "s", "m", "l", "xl", "xxl"] as const;
export const LOGO_POSITIONS = [
  "centerTop",
  "centerBottom",
  "leftTop",
  "leftBottom",
  "rightTop",
  "rightBottom",
] as const;

export type TShirtSize = (typeof T_SHIRT_SIZES)[number];
export type LogoPosition = (typeof LOGO_POSITIONS)[number];

export type RepatingPatternImageUrls = {
  highQualityMobile: string;
  lowQualityMobile: string;
  highQualityDesktop: string;
  lowQualityDesktop: string;
};

export type Video = {
  file: {
    url: string;
    contentType: string;
  };
  altText: string;
  poster?: string;
};

export type GatsbyImageWithAltText = {
  image: IGatsbyImageData;
  altText?: string;
};

export type ColorOverrides = {
  background?: string;
  pausePlayButtonBackground?: string;
  pausePlayButtonIcon?: string;
  buttonBackground?: string;
  buttonText?: string;
};

export type TitleProps = {
  text: RichTextType;
  withBackground?: boolean;
  colorOverrides?: {
    background?: string;
    text?: string;
    dropShadow?: string;
  };
  size?: TShirtSize;
  effect?: { tiltDegrees: number; dropShadow: boolean };
};

export type Props = {
  contentfulId: string;
  nextBlockTypesBlockingPausePlay?: Array<string>;
  contentPosition?: "top" | "middle" | "bottom";
  textAlignment?: "center" | "left";
  firstTitle?: TitleProps;
  secondTitle?: TitleProps;
  callToActionButton?: CallToAction;
  background?: { type: "image" } | { type: "video" }; //TODO add more fields on image and video

  colorOverrides?: ColorOverrides;
  logo?: {
    imageMobile: GatsbyImageWithAltText;
    imageDesktop: GatsbyImageWithAltText;
    position: LogoPosition;
  };
  componentTheme?: ExistingThemes;
  size?: "large" | "small";
  imageMobile?: GatsbyImageWithAltText;
  imageDesktop?: GatsbyImageWithAltText;
  videoMobile?: Video;
  videoDesktop?: Video;
  repeatingPatternImageUrls?: RepatingPatternImageUrls;
  repeatingPatternOpacity?: number;
};

const HeroBlock = ({
  contentfulId,
  nextBlockTypesBlockingPausePlay = [],
  contentPosition = "middle",
  textAlignment = "center",
  callToActionButton,
  colorOverrides,
  imageMobile,
  imageDesktop,
  videoMobile,
  videoDesktop,
  logo,
  firstTitle,
  secondTitle,
  componentTheme,
  size = "large",
  repeatingPatternImageUrls,
  repeatingPatternOpacity,
}: Props) => {
  const buttonUrl = buttonUrlFromCallToAction(callToActionButton);
  const [isPlaying, setIsPlaying] = useState(true);
  const [playPauseStatusMessage, setPlayPauseStatusMessage] = useState<string>("");
  const videoRefMobile = useRef<HTMLVideoElement>(null);
  const videoRefDesktop = useRef<HTMLVideoElement>(null);

  const posterImageMobileUrl = createPosterImageUrl(500, 500, videoMobile?.poster);
  const posterImageDesktopUrl = createPosterImageUrl(1920, 640, videoDesktop?.poster);
  const ultraWideBlurBackgroundImageUrl = createPosterImageUrl(3200, 800, videoDesktop?.poster, true);
  const hasMobileVideo = !!videoMobile;
  const hasDesktopVideo = !!videoDesktop;

  const { blocks } = useCurrentContentPageSlugsContext();
  const indexOfThisBlock = blocks?.findIndex((block) => block.contentfulId === contentfulId);
  const isPausePlayBeingBlockedByNextBlock =
    indexOfThisBlock !== undefined && blocks
      ? nextBlockTypesBlockingPausePlay.includes(blocks[indexOfThisBlock + 1]?.type)
      : undefined;

  const playPausePosition = isPausePlayBeingBlockedByNextBlock ? "LEFT" : "RIGHT";
  const { t } = useTranslation();

  const togglePlayPause = async () => {
    try {
      if (isPlaying) {
        videoRefMobile.current?.pause();
        videoRefDesktop.current?.pause();
        setIsPlaying(false);
        setPlayPauseStatusMessage(t("videoPaused"));
        return;
      } else {
        if (isVideoPausedAndVisible(videoRefMobile.current)) {
          await videoRefMobile.current?.play();
          setIsPlaying(true);
          setPlayPauseStatusMessage(t("videoPlaying"));
          return;
        }
        if (isVideoPausedAndVisible(videoRefDesktop.current)) {
          await videoRefDesktop.current?.play();
          setIsPlaying(true);
          setPlayPauseStatusMessage(t("videoPlaying"));
          return;
        }
      }
    } catch (error) {
      console.error("Error toggling video play/pause:", error);
    }
  };

  useEffect(() => {
    const videoElementMobile = videoRefMobile.current;
    const videoElementDesktop = videoRefDesktop.current;

    if (videoElementMobile || videoElementDesktop) {
      const handlePlay = () => setIsPlaying(true);

      videoElementMobile?.addEventListener("play", handlePlay);
      videoElementDesktop?.addEventListener("play", handlePlay);

      // Check if autoplay was blocked by the browser
      // If it was, update our state to reflect that the video is paused
      if (isVideoPausedAndVisible(videoElementMobile)) {
        setIsPlaying(false);
      }

      if (isVideoPausedAndVisible(videoElementDesktop)) {
        setIsPlaying(false);
      }

      return () => {
        videoElementMobile?.removeEventListener("play", handlePlay);
        videoElementDesktop?.removeEventListener("play", handlePlay);
      };
    }
    return undefined;
  }, []);

  return (
    <section
      data-contentful-id={contentfulId}
      data-size={size}
      style={getStyleOverridesForWrapper(colorOverrides, ultraWideBlurBackgroundImageUrl)}
      className={multipleClassNames(styles.outerWrapper, componentTheme)}
    >
      <SpokenText text={playPauseStatusMessage} ariaLive="polite" />
      {imageMobile && !hasMobileVideo && <Image image={imageMobile} showOnlyOnDeviceType="MOBILE" />}
      {imageDesktop && !hasDesktopVideo && <Image image={imageDesktop} showOnlyOnDeviceType="DESKTOP" />}
      {hasMobileVideo && (
        <BackgroundVideo
          videoRef={videoRefMobile}
          video={videoMobile}
          isPlaying={isPlaying}
          showOnlyOnDeviceType="MOBILE"
          posterImageUrl={posterImageMobileUrl}
        />
      )}
      {hasDesktopVideo && (
        <BackgroundVideo
          videoRef={videoRefDesktop}
          video={videoDesktop}
          isPlaying={isPlaying}
          showOnlyOnDeviceType="DESKTOP"
          posterImageUrl={posterImageDesktopUrl}
        />
      )}
      {logo?.imageMobile && <Logo position={logo.position} image={logo.imageMobile} showOnlyOnDeviceType="MOBILE" />}
      {logo?.imageDesktop && <Logo position={logo.position} image={logo.imageDesktop} showOnlyOnDeviceType="DESKTOP" />}
      {repeatingPatternImageUrls && (
        <div
          style={getStylesOverrideForRepeatingPatternWrapper(repeatingPatternImageUrls, repeatingPatternOpacity)}
          className={styles.repeatingPattern}
        />
      )}
      <div data-content-position={contentPosition} className={styles.contentWrapper}>
        <div data-text-alignment={textAlignment} className={styles.titleWrapper}>
          {firstTitle && <TitleElement Tag="h1" title={firstTitle} />}

          {secondTitle && <TitleElement Tag="h2" title={secondTitle} />}
        </div>
        {callToActionButton?.title && buttonUrl && (
          <SecondaryButtonLink
            url={buttonUrl}
            label={callToActionButton.title}
            openInNewTab={callToActionButton.openInNewTab}
          />
        )}
      </div>
      {(hasMobileVideo || hasDesktopVideo) && (
        <GhostButton
          ariaLabel={t("playPauseVideo")}
          iconSize="l"
          iconCenterNew={isPlaying ? "pause" : "play"}
          className={styles.playPauseButton}
          data-position={playPausePosition.toLocaleLowerCase()}
          onClick={async () => {
            await togglePlayPause();
          }}
        />
      )}
    </section>
  );
};

export default HeroBlock;

type OverridableCssVariablesTitle =
  | "--component-hero-block-tilt-value"
  | "--component-hero-block-text-background-color"
  | "--component-hero-block-text-color-on-background"
  | "--component-hero-block-text-color"
  | "--component-hero-block-text-drop-shadow-color";

const getStyleOverridesForTitle = ({ effect, colorOverrides }: TitleProps) => {
  const styleOverrides = {} as Record<OverridableCssVariablesTitle, string>;

  if (!effect?.tiltDegrees || effect.tiltDegrees < MIN_TILT_DEGREES || MAX_TILT_DEGREES < effect.tiltDegrees) {
    //If it is undefined or outside the bounds, set it to 0deg as default to avoid having undefined or NaN behavior
    styleOverrides["--component-hero-block-tilt-value"] = `0deg`;
  } else {
    styleOverrides["--component-hero-block-tilt-value"] = `${effect.tiltDegrees}deg`;
  }

  if (colorOverrides?.background) {
    styleOverrides["--component-hero-block-text-background-color"] = colorOverrides.background;
  }
  if (colorOverrides?.text) {
    styleOverrides["--component-hero-block-text-color-on-background"] = colorOverrides.text;
    styleOverrides["--component-hero-block-text-color"] = colorOverrides.text;
  }
  if (colorOverrides?.dropShadow) {
    styleOverrides["--component-hero-block-text-drop-shadow-color"] = colorOverrides.dropShadow;
  }

  return styleOverrides as React.CSSProperties;
};

type OverridableCssVariablesWrapper =
  | "--component-hero-block-background-color"
  | "--component-hero-block-pause-play-button-background-color"
  | "--component-hero-block-pause-play-button-icon-color"
  | "--component-hero-block-ultra-wide-background-image"
  | "--component-secondary-button-background"
  | "--component-secondary-button-border"
  | "--component-secondary-button-text";
const getStyleOverridesForWrapper = (colorOverrides: Props["colorOverrides"], desktopVideoPosterImage?: string) => {
  const styleOverrides = {} as Record<OverridableCssVariablesWrapper, string>;

  if (colorOverrides?.background) {
    styleOverrides["--component-hero-block-background-color"] = colorOverrides.background;
  }

  if (colorOverrides?.pausePlayButtonBackground) {
    styleOverrides["--component-hero-block-pause-play-button-background-color"] =
      colorOverrides.pausePlayButtonBackground;
  }

  if (colorOverrides?.pausePlayButtonIcon) {
    styleOverrides["--component-hero-block-pause-play-button-icon-color"] = colorOverrides.pausePlayButtonIcon;
  }

  if (colorOverrides?.buttonBackground) {
    styleOverrides["--component-secondary-button-background"] = colorOverrides.buttonBackground;
    styleOverrides["--component-secondary-button-border"] = colorOverrides.buttonBackground;
  }
  if (colorOverrides?.buttonText) {
    styleOverrides["--component-secondary-button-text"] = colorOverrides.buttonText;
  }

  if (desktopVideoPosterImage) {
    styleOverrides["--component-hero-block-ultra-wide-background-image"] = `url(${desktopVideoPosterImage})`;
  }

  return styleOverrides as React.CSSProperties;
};

type OverridableCssVariablesRepeatingPatternWrapper =
  | "--component-hero-block-repeating-pattern-image-mobile-high-quality"
  | "--component-hero-block-repeating-pattern-image-mobile-low-quality"
  | "--component-hero-block-repeating-pattern-image-desktop-high-quality"
  | "--component-hero-block-repeating-pattern-image-desktop-low-quality"
  | "--component-hero-block-repeating-pattern-image-opacity";

const getStylesOverrideForRepeatingPatternWrapper = (
  repeatingPatternImageUrls: RepatingPatternImageUrls,
  opacity?: number,
) => {
  const styleOverrides = {} as Record<OverridableCssVariablesRepeatingPatternWrapper, string>;

  styleOverrides[
    "--component-hero-block-repeating-pattern-image-mobile-high-quality"
  ] = `url(${repeatingPatternImageUrls.highQualityMobile})`;
  styleOverrides[
    "--component-hero-block-repeating-pattern-image-mobile-low-quality"
  ] = `url(${repeatingPatternImageUrls.lowQualityMobile})`;
  styleOverrides[
    "--component-hero-block-repeating-pattern-image-desktop-high-quality"
  ] = `url(${repeatingPatternImageUrls.highQualityDesktop})`;
  styleOverrides[
    "--component-hero-block-repeating-pattern-image-desktop-low-quality"
  ] = `url(${repeatingPatternImageUrls.lowQualityDesktop})`;

  if (opacity) {
    styleOverrides["--component-hero-block-repeating-pattern-image-opacity"] = `${opacity}`;
  }

  return styleOverrides as React.CSSProperties;
};

const textRenderOptions: Options = {
  renderNode: {
    [BLOCKS.PARAGRAPH]: (node, next) => (
      <>
        {next}
        <br />
      </>
    ),
  },
  renderMark: {
    [MARKS.ITALIC]: (text) => <i>{text}</i>,
    [MARKS.UNDERLINE]: (text) => <u>{text}</u>,
  },
};

const createPosterImageUrl = (width: number, height: number, url: string | undefined, scale?: boolean) => {
  if (!url) return undefined;

  if (!url.includes("//images.ctfassets.net")) {
    //We don't know how to modify non contentful images. The `w=`, `h=`, `q=` and `fm=` are contentful specific.
    return url;
  }
  return `${url}?w=${width}&h=${height}&q=30${scale ? "&fit=scale" : ""}&fm=webp`;
};

const isVideoPausedAndVisible = (videoElement: HTMLVideoElement | null) => {
  const videoElementParent = videoElement?.parentElement;
  if (!videoElementParent) return false;
  return videoElement?.paused && window.getComputedStyle(videoElementParent).display !== "none";
};

type WithShowOnlyOnDeviceType<T> = T & {
  showOnlyOnDeviceType: "MOBILE" | "DESKTOP";
};

const Image = ({
  image,
  showOnlyOnDeviceType,
}: WithShowOnlyOnDeviceType<{
  image: GatsbyImageWithAltText;
}>) => {
  return (
    <div
      className={multipleClassNames(
        styles.imageWrapper,
        showOnlyOnDeviceType === "MOBILE" ? styles.showOnlyOnMobile : styles.showOnlyOnDesktop,
      )}
      data-testid={`hero-image-${showOnlyOnDeviceType}`}
    >
      <GatsbyImage image={image.image} alt={image.altText ?? "Background image"} className={styles.gatsbyImage} />
    </div>
  );
};

const BackgroundVideo = ({
  videoRef,
  video,
  isPlaying,
  showOnlyOnDeviceType,
  posterImageUrl,
}: WithShowOnlyOnDeviceType<{
  videoRef: RefObject<HTMLVideoElement>;
  video: Video;
  isPlaying: boolean;
  posterImageUrl?: string;
}>) => {
  return (
    <>
      <div
        className={multipleClassNames(
          styles.videoWrapper,
          showOnlyOnDeviceType === "MOBILE" ? styles.showOnlyOnMobile : styles.showOnlyOnDesktop,
        )}
        data-testid={`hero-video-${showOnlyOnDeviceType}`}
      >
        <video
          ref={videoRef}
          autoPlay
          loop
          muted
          playsInline
          poster={posterImageUrl}
          aria-label={video.altText ?? "Hero video"}
        >
          <source
            src={video.file.url}
            media={showOnlyOnDeviceType === "DESKTOP" ? breakpoints.large : `not ${breakpoints.large}`}
            type={video.file.contentType}
          />
        </video>
      </div>
      {!isPlaying && <div className={styles.pausedOverlay}></div>}
    </>
  );
};

const Logo = ({
  position,
  image,
  showOnlyOnDeviceType,
}: WithShowOnlyOnDeviceType<{
  position: NonNullable<Props["logo"]>["position"];
  image: NonNullable<Props["logo"]>["imageMobile" | "imageDesktop"];
}>) => {
  return (
    <div
      className={multipleClassNames(
        styles.logoPosition,
        showOnlyOnDeviceType === "MOBILE" ? styles.showOnlyOnMobile : styles.showOnlyOnDesktop,
      )}
      data-position={position}
      data-testid={`hero-logo-${showOnlyOnDeviceType}`}
    >
      <GatsbyImage image={image.image} alt={image.altText ?? "Logo"} />
    </div>
  );
};

const TitleElement = ({ Tag, title }: { Tag: "h1" | "h2"; title: TitleProps }) => {
  return (
    <div style={getStyleOverridesForTitle(title)}>
      <Tag
        data-has-background={!!title.withBackground}
        data-has-drop-shadow={!!title.effect?.dropShadow}
        data-size={title.size}
      >
        {documentToReactComponents(JSON.parse(title.text.raw), textRenderOptions)}
      </Tag>
    </div>
  );
};
